/* Receptek. Hozzávaló-sor: [?=nem kötelező][!=nem kell venni, pl. víz]Kulcs1/Kulcs2[*szorzó] menny egység=megjelenő név
   A kulcsok a termékkészlet nevei. Kategóriák: leves, hus, hal, foz, teszta, zoldseg, salata, szendvics, hidegtal, hideg, reggeli, desszert, egyeb.
   Jelzők: h = hideg étel, w = meleg (pl. melegszendvics), m = gyors mini étel (nem von le mennyiséget). */
function R(id,nev,cat,adag,ido,ing,lep,krit,allerg,tal,fl){
  return{id:id,nev:nev,cat:cat,adag:adag,ido_perc:ido,hozzavalok:ing.split(";").map(pIng).filter(Boolean),
    lepesek:lep?lep.split("|"):[],kritikus:krit?krit.split("|"):[],allergenek:allerg?allerg.split(","):[],talalas:tal||"",
    hideg:fl&&fl.indexOf("h")>=0?1:0,mini:fl&&fl.indexOf("m")>=0?1:0,meleg:fl&&fl.indexOf("w")>=0?1:0};
}
function pIng(s){s=s.trim();if(!s)return null;
  var m=/^([?!]*)(.+?)(?:\s+([\d.,]+)\s*([a-zA-Záéíóöőúüű]+))?(?:\s*=\s*(.+))?$/.exec(s);
  /* kulcs*szorzó: az adott változatból ennyiszer annyi kell (pl. Bab konzerv*2.4 = a szárazbab súlyának 2,4-szerese, főzve) */
  var kf=null,keys=m[2].split("/").map(function(x){var p=/^(.+?)\*([\d.]+)$/.exec(x.trim());if(p){kf=kf||{};kf[p[1].trim()]=parseFloat(p[2]);return p[1].trim()}return x.trim()}),h={nev:m[5]||keys.map(function(k){return k.toLowerCase()}).join(" vagy "),k:keys};if(kf)h.kf=kf;
  if(m[3]){h.menny=parseFloat(m[3].replace(",","."));h.egyseg=m[4]}
  if(m[1].indexOf("?")>=0)h.o=1;if(m[1].indexOf("!")>=0){h.f=1;h.k=[]}
  return h}

